import Foundation
import Observation

/// One chain from `SeedChains.json`, generated by `scripts/build_chains.py`.
/// Only chains with researched evidence (docs/data/chain_evidence.json) carry a
/// grade; every grade has a confidence, a basis, and at least one source.
nonisolated struct ChainInfo: Codable, Sendable {
    let slug: String
    let name: String
    let category: String?
    let parentCompany: String?
    /// Other names the chain goes by (from the curated list and NSI `matchNames`).
    let aliases: [String]?
    /// Where the entry came from: "curated", "nsi", "wikipedia", or "evidence".
    let provenance: String?
    let wikidata: String?
    /// `SlopRating` raw value; nil when the chain hasn't been graded.
    let grade: String?
    let confidence: GradeConfidence?
    let basis: String?
    let sources: [GradeSource]?

    var citedRating: SlopRating? {
        grade.flatMap(SlopRating.init(rawValue:)).flatMap { $0.isGraded ? $0 : nil }
    }

    var isGraded: Bool { citedRating != nil }
}

@Observable
final class ChainDatabase {
    private(set) var chains: [String: ChainInfo] = [:]

    /// Normalized name or alias → slug.
    private var exact: [String: String] = [:]
    /// Same keys with spaces removed, so "Chick fil A" finds "chickfila".
    private var compact: [String: String] = [:]
    /// First token → (all tokens, slug), for "<chain name> <suffix>" matches.
    private var byFirstToken: [String: [(tokens: [String], slug: String)]] = [:]

    init(resource: String = "SeedChains", bundle: Bundle = .main) {
        guard let url = bundle.url(forResource: resource, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let items = try? JSONDecoder().decode([ChainInfo].self, from: data) else {
            return
        }
        load(items)
    }

    init(chains items: [ChainInfo]) {
        load(items)
    }

    private func load(_ items: [ChainInfo]) {
        // Graded entries come first in the file, so they win any name collision.
        var cores: [(tokens: [String], slug: String)] = []
        for item in items where chains[item.slug] == nil {
            chains[item.slug] = item
            for name in [item.name] + (item.aliases ?? []) {
                let tokens = Self.tokens(name)
                guard !tokens.isEmpty, !Self.isGeneric(tokens) else { continue }
                // Weak names ("Jack's", "La Salsa") only match exactly, so "Jack's
                // Pizza" and "La Salsa Verde Taqueria" stay independent. Curated
                // chains keep prefix matching ("McDonald's Restaurant").
                let weak = item.provenance != "curated" && Self.isWeak(name: name, tokens: tokens)
                index(tokens, slug: item.slug, allowPrefix: !weak)
                if let core = Self.core(of: name, tokens: tokens) {
                    cores.append((core, item.slug))
                }
            }
        }
        // Full names first, so a core never shadows another chain's real name.
        // Cores only match exactly: "Longhorn" is LongHorn Steakhouse, but
        // "Longhorn Cafe" is not.
        for core in cores {
            index(core.tokens, slug: core.slug, allowPrefix: false)
        }
    }

    private func index(_ tokens: [String], slug: String, allowPrefix: Bool = true) {
        let key = tokens.joined(separator: " ")
        if exact[key] == nil { exact[key] = slug }
        let squashed = tokens.joined()
        if compact[squashed] == nil { compact[squashed] = slug }
        if allowPrefix, !byFirstToken[tokens[0], default: []].contains(where: { $0.tokens == tokens }) {
            byFirstToken[tokens[0], default: []].append((tokens, slug))
        }
    }

    /// One distinctive word that is a possessive ("Jack's") or follows an
    /// article ("La Salsa", "El Pollo"): common in independent restaurant names.
    nonisolated static func isWeak(name: String, tokens: [String]) -> Bool {
        let articles: Set<String> = ["a", "an", "el", "la", "las", "los", "le", "il", "de"]
        let distinctive = tokens.drop { articles.contains($0) }
        guard distinctive.count == 1 else { return false }
        if distinctive.count < tokens.count { return true }
        let firstWord = name.split(separator: " ").first ?? ""
        return firstWord.contains("'") || firstWord.contains("\u{2019}")
    }

    /// A chain name without its trailing generic words, so "Intelligentsia" finds
    /// "Intelligentsia Coffee & Tea" and "Krispy Kreme" finds "Krispy Kreme
    /// Doughnuts". A one-word core must be at least six letters and not a
    /// possessive, so "Joe's Pizza" doesn't claim every "Joe's".
    nonisolated static func core(of name: String, tokens: [String]) -> [String]? {
        var core = tokens
        while let last = core.last, core.count > 1, descriptors.contains(last) {
            core.removeLast()
        }
        guard core.count < tokens.count, !isGeneric(core) else { return nil }
        if core.count == 1 {
            let firstWord = name.split(separator: " ").first ?? ""
            let isPossessive = firstWord.contains("'") || firstWord.contains("\u{2019}")
            guard core[0].count >= 6, !isPossessive else { return nil }
        }
        return core
    }

    func lookup(slug: String) -> ChainInfo? {
        chains[slug]
    }

    /// Matches a place name to a chain.
    ///
    /// 1. Exact match of the cleaned, normalized name (or any part of a
    ///    "KFC/Taco Bell" combo) against chain names and aliases.
    /// 2. The chain's full name followed by more words ("Olive Garden Italian
    ///    Restaurant", "Shake Shack West End"), when `allowPrefix` is true. A
    ///    one-word chain name only matches this way if what follows is generic
    ///    ("Sonic Drive-In"), so "Paul Martin's American Grill" isn't "Paul".
    ///
    /// A place name only matches a longer chain name when the chain's extra
    /// words are generic (see `core(of:tokens:)`), and words only match whole
    /// words, so "Pizza" can't become "Pizza Hut" and "The Star" can't become
    /// "Starbucks".
    func match(name: String, allowPrefix: Bool = true) -> ChainInfo? {
        let candidates = Self.candidateTokens(for: name)

        for tokens in candidates where !Self.isGeneric(tokens) {
            if let slug = exact[tokens.joined(separator: " ")] ?? compact[tokens.joined()] {
                return chains[slug]
            }
        }

        guard allowPrefix else { return nil }
        for tokens in candidates {
            if let info = prefixMatch(tokens) { return info }
        }
        return nil
    }

    private func prefixMatch(_ tokens: [String]) -> ChainInfo? {
        guard let first = tokens.first, let options = byFirstToken[first] else { return nil }
        var best: (count: Int, slug: String)?
        for option in options {
            let key = option.tokens
            guard key.count < tokens.count, Array(tokens.prefix(key.count)) == key else { continue }
            let rest = tokens.dropFirst(key.count)
            if key.count == 1 {
                guard key[0].count >= 3, rest.allSatisfy(Self.descriptors.contains) else { continue }
            }
            if key.count > (best?.count ?? 0) {
                best = (key.count, option.slug)
            }
        }
        return best.flatMap { chains[$0.slug] }
    }

    // MARK: - Normalization

    /// Lowercase ASCII words: diacritics folded, "&" → "and", apostrophes
    /// dropped ("McDonald's" → "mcdonalds"), other punctuation → space, and a
    /// leading "the" removed. Mirrors `normalize` in scripts/build_chains.py.
    nonisolated static func normalize(_ name: String) -> String {
        tokens(name).joined(separator: " ")
    }

    nonisolated static func tokens(_ name: String) -> [String] {
        var scalars = String.UnicodeScalarView()
        for scalar in name.decomposedStringWithCompatibilityMapping.unicodeScalars {
            switch scalar {
            case _ where scalar.properties.generalCategory == .nonspacingMark:
                continue
            case "'", "\u{2019}", "\u{2018}", "`":
                continue
            case "&", "+":
                scalars.append(contentsOf: " and ".unicodeScalars)
            case "A"..."Z", "a"..."z", "0"..."9":
                scalars.append(contentsOf: String(scalar).lowercased().unicodeScalars)
            default:
                scalars.append(" ")
            }
        }
        var words = String(scalars).split(separator: " ").map(String.init)
        if words.first == "the", words.count > 1 {
            words.removeFirst()
        }
        return words
    }

    /// Normalized token lists to try for a place name: the full name, the name
    /// with a location or store-number suffix removed, and each half of a
    /// "Brand A / Brand B" combo.
    nonisolated static func candidateTokens(for name: String) -> [[String]] {
        var forms = [name]
        var base = name
        for separator in [" - ", " – ", " — ", " | ", " @ ", " (", ", "] {
            if let range = base.range(of: separator) {
                base = String(base[..<range.lowerBound])
            }
        }
        base = base.replacingOccurrences(
            of: #"(?i)\s*(#|\bno\.?\s*|\bstore\s*#?|\bunit\s*#?)\s*\d+\b.*$|\s+\d{3,}$"#,
            with: "",
            options: .regularExpression
        )
        forms.append(base)
        if base.contains("/") {
            forms += base.split(separator: "/").map(String.init)
        }

        var seen = Set<[String]>()
        return forms.map(tokens).filter { !$0.isEmpty && seen.insert($0).inserted }
    }

    /// True when every word is generic, like "pizza" or "burger bar".
    nonisolated static func isGeneric(_ tokens: [String]) -> Bool {
        tokens.allSatisfy { genericWords.contains($0) || descriptors.contains($0) }
    }

    /// Words that name a kind of food or place, never a brand on their own.
    nonisolated static let genericWords: Set<String> = [
        "bagel", "bagels", "bbq", "bakery", "bar", "barbecue", "bistro", "breakfast",
        "buffet", "burger", "burgers", "burrito", "burritos", "cafe", "cafeteria",
        "cantina", "chicken", "chinese", "coffee", "creamery", "deli", "diner",
        "donut", "donuts", "doughnut", "doughnuts", "dumpling", "dumplings", "food",
        "foods", "gelato", "grill", "gyro", "gyros", "hot", "dog", "dogs", "juice",
        "kebab", "kitchen", "noodle", "noodles", "pasta", "pho", "pizza", "pizzeria",
        "poke", "pub", "ramen", "restaurant", "salad", "sandwich", "sandwiches",
        "seafood", "shawarma", "smoothie", "smoothies", "steak", "steakhouse",
        "sub", "subs", "sushi", "taco", "tacos", "taqueria", "tea", "wing", "wings",
    ]

    /// Generic words that can follow a one-word chain name ("Sonic Drive In",
    /// "Chipotle Mexican Grill") without making it a different place.
    nonisolated static let descriptors: Set<String> = [
        "and", "american", "asian", "bagel", "bagels", "bakery", "bar", "barbecue",
        "bbq", "bowl", "bowls", "brewery", "brewhouse", "brewing", "burger", "burgers",
        "cafe", "chicken", "co", "coffee", "company", "cookies", "cream", "creamery",
        "cuisine", "custard", "deli", "diner", "donuts", "doughnuts", "drive", "eatery",
        "espresso", "express", "fresh", "fries", "frozen", "grill",
        "ice", "in", "italian", "japanese", "juice", "kitchen", "mexican", "of",
        "pizza", "pizzeria", "pub", "restaurant", "restaurants", "roasters",
        "salad", "sandwiches", "seafood", "shakes", "shop", "smoothies", "southwest",
        "steakhouse", "subs", "sushi", "taco", "tacos", "tavern", "tea", "thru",
        "through", "wings", "yogurt",
    ]
}
